// Define the scalar types as described in the problem
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NumpyScalarType {
    Int64,
    Float64,
    Complex128,
    String,
    Bool,
}

// Define the different types of objects that can be passed
pub enum NumpyObject {
    Integer(i64),
    Float(f64),
    IntArray(Vec<i64>),
    FloatArray(Vec<f64>),
    ComplexArray(Vec<(f64, f64)>), // pairs representing complex numbers (real, imag)
    String(String),
    Boolean(bool),
    Generic, // object without specific type information
}

fn obj2sctype(rep: NumpyObject, default: Option<NumpyScalarType>) -> Option<NumpyScalarType> {
    match rep {
        // For integer values, return Int64
        NumpyObject::Integer(_) => Some(NumpyScalarType::Int64),
        
        // For floating-point values, return Float64
        NumpyObject::Float(_) => Some(NumpyScalarType::Float64),
        
        // For arrays of integers, return Int64
        NumpyObject::IntArray(_) => Some(NumpyScalarType::Int64),
        
        // For arrays of floats, return Float64
        NumpyObject::FloatArray(_) => Some(NumpyScalarType::Float64),
        
        // For arrays of complex pairs, return Complex128
        NumpyObject::ComplexArray(_) => Some(NumpyScalarType::Complex128),
        
        // For string values, return String
        NumpyObject::String(_) => Some(NumpyScalarType::String),
        
        // For boolean values, return Bool
        NumpyObject::Boolean(_) => Some(NumpyScalarType::Bool),
        
        // For generic objects, return the provided default
        NumpyObject::Generic => default,
    }
}

// Example usage and tests
fn main() {
    // Test cases
    let int_obj = NumpyObject::Integer(42);
    assert_eq!(obj2sctype(int_obj, None), Some(NumpyScalarType::Int64));
    
    let float_obj = NumpyObject::Float(3.14);
    assert_eq!(obj2sctype(float_obj, None), Some(NumpyScalarType::Float64));
    
    let int_array = NumpyObject::IntArray(vec![1, 2, 3]);
    assert_eq!(obj2sctype(int_array, None), Some(NumpyScalarType::Int64));
    
    let float_array = NumpyObject::FloatArray(vec![1.0, 2.0, 3.0]);
    assert_eq!(obj2sctype(float_array, None), Some(NumpyScalarType::Float64));
    
    let complex_array = NumpyObject::ComplexArray(vec![(1.0, 2.0), (3.0, 4.0)]);
    assert_eq!(obj2sctype(complex_array, None), Some(NumpyScalarType::Complex128));
    
    let string_obj = NumpyObject::String("hello".to_string());
    assert_eq!(obj2sctype(string_obj, None), Some(NumpyScalarType::String));
    
    let bool_obj = NumpyObject::Boolean(true);
    assert_eq!(obj2sctype(bool_obj, None), Some(NumpyScalarType::Bool));
    
    // Test generic object with default
    let generic_obj = NumpyObject::Generic;
    assert_eq!(obj2sctype(generic_obj, Some(NumpyScalarType::Int64)), Some(NumpyScalarType::Int64));
    
    // Test generic object without default
    let generic_obj = NumpyObject::Generic;
    assert_eq!(obj2sctype(generic_obj, None), None);
    
    // Test that default is ignored for non-generic objects
    let int_obj = NumpyObject::Integer(42);
    assert_eq!(obj2sctype(int_obj, Some(NumpyScalarType::Float64)), Some(NumpyScalarType::Int64));
    
    println!("All tests passed!");
}